window.REPORT_PRELOAD_CACHE["ARM.html"] = {"version":"8f4e59ae1fb72d31f9a2ed24d973bad716ee3b993448e392e31e58b618b4c4fd","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>安谋科技 Arm Holdings (NASDAQ: ARM) 深度研究报告：从移动端 IP 霸主到 AI 数据中心与物理智能计算基石</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n armblue: {\n 400: '#38BDF8',\n 500: '#0091BD',\n 600: '#0284C7',\n },\n accent: {\n 500: '#3B82F6',\n 600: '#2563EB',\n },\n teal: {\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(0, 145, 189, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n border-left: 3px solid #0091BD;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-armblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-armblue-500 via-cyan-400 to-teal-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-armblue-500 to-armblue-600 flex items-center justify-center font-extrabold text-white shadow\">\n arm\n </div>\n <div>\n <div class=\"text-[11px] text-armblue-400 font-semibold tracking-wider uppercase\">NASDAQ: ARM · Equity Research</div>\n <div class=\"text-sm font-bold leading-tight\">安谋科技 Arm Holdings 深度报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端抽屉 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">ARM 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 商业模式与收入架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值解析</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球半导体与 IP 架构研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (FY26 / FY27E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边栏 -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-armblue-500 to-armblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-armblue-500/25\">\n arm\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-armblue-400 bg-armblue-500/15 px-2 py-0.5 rounded\">NASDAQ: ARM</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">安谋科技深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球半导体计算架构基石 · 从移动授权垄断向云端 AI 与 AGI CPU 演进\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY26 全年总营收</span>\n <span class=\"font-mono font-bold text-white\">~$3.9B–$4.0B <span class=\"text-armblue-400\">(+25%+)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY27E 营收共识</span>\n <span class=\"font-mono font-bold text-teal-400\">~$6.06B <span class=\"text-slate-400\">(+23%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">毛利率水平 (GAAP)</span>\n <span class=\"font-mono font-bold text-armblue-400\">~97.1% (顶级 IP 模式)</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-armblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与收入架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-armblue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-armblue-500 hover:bg-armblue-600 text-white text-xs font-extrabold transition shadow-sm\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- 00. 封面与执行摘要 -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-armblue-500/15 text-armblue-600 dark:text-armblue-400 font-bold border border-armblue-500/30\">评级：买入 / 核心科技底仓配置</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2031 架构升级与 AGI CPU 突破</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NASDAQ: ARM</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#0091BD 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-armblue-500/20 border border-armblue-500/40 text-armblue-400 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-armblue-400 animate-pulse\"></span>\n <span>CORE THESIS · 从移动端 IP 授权垄断向云端 AI、CSS 子系统与自研 AGI CPU 第二增长曲线跃迁</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 安谋科技 Arm Holdings (NASDAQ: ARM) 深度研究报告：全球半导体计算架构基石，开启 AI 数据中心与物理智能计算新纪元\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n Arm 作为全球超过 99% 智能手机与千亿边缘设备的底层指令集架构（ISA）垄断者，正迎来历史上最具爆发力的商业模式升级。FY26 营业额持续强劲增长，其中 Q2 总营收创下历史新高的 <strong class=\"text-armblue-400\">$1.44B (+27% YoY)</strong>，GAAP 毛利率高达 <strong class=\"text-teal-400\">97.1%</strong>。\n 随着 AWS Graviton、Google Axion、Microsoft Cobalt 以及云巨头深度定制芯片的普及，结合 <strong class=\"text-white\">Arm AGI CPU</strong> 在服务器机柜端展现出 2 倍于传统 x86 的 agentic 效能，公司正从单纯的“收取版税与授权费”向<strong class=\"text-armblue-400\">完整计算子系统（CSS）与芯片级方案</strong>延展，FY27–FY28 AGI CPU 承诺营收已锁定高达 <strong class=\"text-emerald-400\">~$20 亿</strong>。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">极极致盈利与高毛利</div>\n <div class=\"text-white font-semibold\">GAAP 毛利率稳定在 97.1% – 97.9%，研发投入强度支撑 CSS 与 AGI CPU 长期壁垒</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">云与数据中心份额跃升</div>\n <div class=\"text-armblue-400 font-semibold\">基于 Neoverse CSS 的云端 CPU 渗透率持续攀升，年末市场占有率向 60% 迈进</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">第二增长曲线开启</div>\n <div class=\"text-teal-400 font-semibold\">Arm AGI CPU 在 FY27-FY28 带来高达 $20B 级别潜力，远期向 FY31 $15B 芯片营收进军</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q2 FY27 季度总营收</span>\n <span class=\"p-1.5 rounded-lg bg-armblue-500/15 text-armblue-600 dark:text-armblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.44B</span>\n <span class=\"text-xs font-bold text-armblue-600 dark:text-armblue-400 bg-armblue-500/15 px-2 py-0.5 rounded\">+27% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 创下公司历史最高单季营收纪录，得益于计算子系统（CSS） adoption 与版税持续高速增长。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>GAAP / Non-GAAP 毛利率</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">97.1%</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">Non-GAAP 97.9%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 全球半导体行业绝无仅有的极致 IP 商业模式，带来超高毛利与强大的现金回报潜力。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>年化合同价值 (ACV)</span>\n <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.79B</span>\n <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">+12% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 衡量标准化许可与长期生态签约质量的核心指标稳健增长，Total Access 客户持续拓展。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY2027E 营收共识预测</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$6.06B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">+23% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 数据中心 CSS 与智能汽车、AI PC 持续爆发，推动 Arm 迈入全年 60 亿美元营收新台阶。\n </p>\n </div>\n </div>\n </section>\n\n <!-- 01. 商业模式与收入架构 -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-armblue-600 dark:text-armblue-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与收入架构：双轮驱动（授权许可 License + 芯片版税 Royalty）</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">ACV 达 $1.79B · 长期 Total Access 客户超 55 家</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2023–FY2028E 营收结构演进（授权费 vs 版税版图）</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">版税收入稳居基本盘，CSS 与 AGI 芯片带来二次增长曲线</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-armblue-600 dark:text-armblue-400 shadow-sm transition\">视图A：营收演进</button>\n <button onclick=\"switchBizChart('model_split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：业务条线拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大核心支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-armblue-500/15 text-armblue-600 dark:text-armblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">许可证费用（Licensing & ACV）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 客户在设计芯片阶段支付 upfront 授权费。ACV（年化合同价值）达 <strong>$1.79B (+12% YoY)</strong>，Extant Total Access 长期深度授权客户增至 <strong>56家</strong>。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">芯片版税（Royalty Revenue）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 每当全球合作伙伴售出一颗包含 Arm 架构的芯片（手机、汽车、IoT、云服务器），Arm 即按出货量与芯片价值比例收取版税。V9 架构占比提升显著提高单芯片版税率。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">计算子系统（CSS）与 AGI CPU 突破</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 从单纯交付 IP 转向打包交付预集成好的计算子系统（Neoverse CSS），并切入 AGI CPU 芯片销售（FY27-FY28 目标达 ~$20 亿），显著增厚单机价值量。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">核心业务延展</span>\n <span class=\"font-bold text-armblue-600 dark:text-armblue-400\">Neoverse CSS N4 / V3 与 AGI CPU 芯片</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-armblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-armblue-500/15 text-armblue-600 dark:text-armblue-400 text-xs font-bold\">核心支柱 · 智算与云服务</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">云与数据中心</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">1. 云端与数据中心（Cloud & Datacenter）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 依托 AWS Graviton、Google Axion、Microsoft Cobalt 与 NVIDIA Blackwell/Rubin 平台，Arm 架构在云服务器渗透率加速，预期到 2026 年底份额将突破 <strong>60%</strong>。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-armblue-600 dark:text-armblue-400 font-semibold\">\n Neoverse CSS N4/V3 · 架构份额 &gt;60%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">基本盘 · 绝对垄断</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">移动端与 PC</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. 移动设备与 AI PC（Mobile & PC）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 全球智能手机架构市占率稳居 <strong>99%</strong>。随着 Armv9 架构渗透率提升及高通 Snapdragon X / 苹果 M 系列芯片在 AI PC 领域的扩张，版税率实现量价齐升。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n 智能手机 99% 垄断 · V9 架构单价提升\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">高速增长 · 物理智能</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">汽车与物联网</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. 汽车与物理智能 / IoT（Automotive & Edge）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 物理 AI 与智能座舱/智驾系统（如特斯拉 FSD、L4 Robocar 单车采用超 400 个 Arm CPU 核心）版税同比大增 <strong>50%</strong>，Arm Total Design 汇聚超 80 家生态伙伴。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n 物理 AI 版税 +50% YoY · 80+ 生态联盟\n </div>\n </div>\n </div>\n </section>\n\n <!-- 02. 行业地位与四重核心护城河 -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：全球 2200 万开发者的网络效应</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 不可替代的指令集与软件生态基石)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-armblue-500/15 text-armblue-600 dark:text-armblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球最大的 2200 万+ 开发者生态</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 从编译工具链（GCC、LLVM）、操作系统（Linux、Android、Windows on Arm）到各大 AI 框架（TensorFlow、PyTorch），全球超过 <strong>2200 万软件开发者</strong>的代码底层全部基于 Arm 架构。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">极致的能效比（Performance-per-Watt）</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n RISC（精简指令集）架构天生具备低功耗优势。在数据中心电网负荷逼近极限的今天，Arm Neoverse 与 AGI CPU 能够以更低功耗提供卓越的 agentic AI 推理效能。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">轻资产 IP 商业模式与高客户粘性</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 采取不直接生产芯片的 Fabless IP 授权模式，与台积电、三星、SK 海力士及所有主流芯片设计公司深度绑定，几乎分享了整个全球半导体成长红利。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">计算子系统（CSS）垂直整合溢价</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 从交付纯指令集 IP 升级为交付完整打包的 Neoverse CSS。Arm 承担更多前端系统设计，使客户能够缩短 1 年以上研发周期并向 Arm 支付更高价值量的复合版税。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">Arm 架构核心竞争优势五维度量化雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Arm vs 传统 x86 (Intel/AMD) vs RISC-V 开源架构 (满分 10 分)</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 03. 同行竞争格局横向对比 -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-armblue-600 dark:text-armblue-400\">Section 03 · Global Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三, 同行竞争格局横向对比：x86 守城，RISC-V 追赶，Arm 领跑 AI 时代</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-armblue-500 text-white shadow-sm transition\">全部阵营</button>\n <button onclick=\"filterCompetitors('x86')\" data-filter=\"x86\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">传统 x86 架构巨头</button>\n <button onclick=\"filterCompetitors('riscv')\" data-filter=\"riscv\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">开源 RISC-V 挑战者</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">竞争架构与标的</th>\n <th class=\"py-4 px-4 min-w-[130px]\">软件生态成熟度</th>\n <th class=\"py-4 px-4 min-w-[140px]\">AI 与服务器渗透率</th>\n <th class=\"py-4 px-4 min-w-[135px]\">移动与边缘市占</th>\n <th class=\"py-4 px-4 min-w-[115px]\">毛利率水平</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争关系评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"core\" class=\"bg-armblue-500/5 dark:bg-armblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-armblue-500 text-white text-[10px] font-extrabold\">绝对标杆</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">Arm Holdings (ARM)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Armv9 / Neoverse CSS / AGI CPU</div>\n </td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">2200万开发者 行业绝对核心</span>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">AWS/Google/MS云CPU加速渗透 (~60%)</td>\n <td class=\"py-4 px-4 font-bold text-armblue-600 dark:text-armblue-400\">智能手机 &gt;99% 垄断</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~97.1% (GAAP)</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>绝对领跑者：</strong>唯一横跨移动、汽车、云端AI的计算架构，CSS与AGI CPU打开第二成长空间。\n </td>\n </tr>\n\n <tr data-category=\"x86\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Intel (INTC x86架构)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Xeon 6 / 传统服务器 CPU</div>\n </td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">传统服务器深度绑定 (x86遗留生态)</span>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">份额持续被 Arm 云CPU分流</td>\n <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">PC 端仍存优势但受挤压</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~35% - 42%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>守势防御：</strong>在传统 enterprise 服务器仍具基盘，但受制于高功耗与代工转型拖累，AI 时代的能效比劣势明显。\n </td>\n </tr>\n\n <tr data-category=\"x86\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">AMD (AMD EPYC x86)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">EPYC Turin / 霄龙处理器</div>\n </td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-accent-500/15 text-accent-700 dark:text-accent-400\">x86 服务器高性能标杆</span>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">数据中心通用服务器主力 (~30%)</td>\n <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">移动端份额相对较小</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~50% - 54%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>强力竞争者：</strong>凭借高核心数 EPYC 在企业级虚拟化和通用超算占据强劲份额，但能效比面临 Arm Neoverse 架构的强力挑战。\n </td>\n </tr>\n\n <tr data-category=\"riscv\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">RISC-V 开源生态阵营</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">SiFive / Andes / 嵌入式 MCU</div>\n </td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-rose-500/10 text-rose-600 dark:text-rose-400\">软件生态碎片化 (早期发展中)</span>\n </td>\n <td class=\"py-4 px-4 text-slate-600 dark:text-slate-300\">主要集中在物联网与协处理器</td>\n <td class=\"py-4 px-4 text-rose-600 dark:text-rose-400 font-semibold\">边缘 IoT 持续蚕食低端</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">无统一商业化毛利参考</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>长期开源威胁：</strong>免授权费特性在物联网微控制器（MCU）和专用加速器中发展迅速，但在高性能计算和统一软件生态上短期无法对 Arm 构成实质威胁。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">半导体计算架构核心毛利率与盈利模式对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">Arm 凭借纯 IP 授权与 CSS 模式实现 ~97% 业界绝无仅有的毛利率表现</p>\n </div>\n <span class=\"text-xs font-semibold text-armblue-600 dark:text-armblue-400 bg-armblue-500/15 px-2.5 py-1 rounded\">极致轻资产 IP 商业模式</span>\n </div>\n <div class=\"relative h-60 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- 04. 财务健康与估值体系解析 -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：高毛利、高研发投入与成长溢价</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">远期 Forward P/E 处于高位区间 · 支撑于 AI 服务器与 AGI CPU 长期高成长</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-armblue-600 dark:text-armblue-400 uppercase\">Gross Margin (GAAP)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">97.1% – 97.9%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 全球半导体上市公司中最高的毛利率水平，几乎不受晶圆厂制造成本或通胀周期波动的直接挤压。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">R&D Investment</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$857M / 季</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q2 FY27 研发费用同比增长 24% YoY，持续加码下一代 AI CPU、CSS 子系统与软件生态人才招聘。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Operating Cash Flow</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$1.11B (H1)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n H1 营业现金流表现稳健（对比去年同期 $899M 进一步增长），现金及短期投资储备达 $36.2 亿。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">FY27E Revenue Growth</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$6.06B (+23%)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 华尔街一致预期显示，随着 Neoverse CSS 与 AGI CPU 落地，Arm 正在稳步跨越年营收 60 亿美元大关。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2023–FY2028E 营收持续扩张与长期盈利增长趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">版税率结构性抬升与芯片业务突破带来强劲长期复利增长</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded\">FY31 目标：营收超 $15B+ (含芯片业务)</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">AI 计算不可替代基石</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>云端计算架构渗透率加速：</strong>AWS、Google、微软及 NVIDIA 平台全面采用 Neoverse CSS，云端版税实现三位数复合增长。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>AGI CPU 芯片营收打开百亿新空间：</strong>管理层对 FY27-FY28 达 ~$20 亿 AGI CPU 充满信心，远期向 FY31 $150 亿芯片销售迈进。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Armv9 架构价值量跃升：</strong>V9 版税率是 V8 的两倍以上，随着高端手机与 AI PC 渗透率提升，版税收入质量大幅优化。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">高估值与集中度风险</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"rose-text font-bold text-rose-600\">!</span><span><strong>高企的 forward P/E 估值倍数：</strong>市场前期赋予其极高估值预期，任何季度业绩或指引的微小波动都可能引发股价剧烈回调。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"rose-text font-bold text-rose-600\">!</span><span><strong>大客户集中度较高：</strong>前五大客户（包括 Arm China 及 SoftBank 关联生态）占总净营收近 57%，客户流失或纠纷风险需持续监控。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"rose-text font-bold text-rose-600\">!</span><span><strong>消费电子换机周期波动：</strong>智能手机与 PC 市场若受宏观或高内存成本拖累出现出货下滑，短期手机版税增速可能面临阶段性降温。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- 05. 投资决策与风险配置框架 -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-armblue-600 dark:text-armblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与机构风控纪律</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：科技组合高成长核心底仓 · 逢回调分批建仓</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-armblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-armblue-500/15 text-armblue-600 dark:text-armblue-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-armblue-600 dark:text-armblue-400\">概率：30%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">核心成长驱动：AGI CPU 超预期</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>AGI CPU 在 FY27-FY28 达成超 $20 亿上限，云厂商加速全面转向 Arm Neoverse CSS 架构，AI PC 渗透率暴增，授权费与版税复合增速超预期。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-armblue-600 dark:text-armblue-400\">\n 潜在上行空间：+40% 至 +55%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">核心成长驱动：营收稳健达 ~$6.06B</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>FY27E 营收如期达成 ~23% 增长，移动端 V9 版税按节奏兑现，云端与汽车物理 AI 版税保持 50%+ 稳定高增，估值在盈利消化下逐步趋于合理。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n 潜在上行空间：+20% 至 +30%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守下行风险：估值多重收缩</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>消费电子需求显著萎缩导致手机版税下滑，云厂商资本开支周期放缓延缓 AGI CPU 商业化，高估值泡沫面临挤压。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在下行回撤：-20% 至 -30%\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 客户集中度与诉讼风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">前五大客户占比 ~57% 及知识产权/版税合同纠纷</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管诉讼判决（如近期与高通相关裁决）影响可控，但高度集中的大客户结构意味着核心伙伴的战略调整对 Arm 营收具有决定性影响。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 宏观周期与消费电子波动</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">智能手机与 PC 换机周期及内存成本上涨抑制</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 手机版税仍是当前重要基盘。若终端设备因元器件（如高价 HBM/DRAM）成本上升导致出货量受阻，可能对版税增长带来 1%–2% 的短期摩擦。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · AGI 芯片供应链与产能制约</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">先进制程晶圆与先进封装产能分配限制</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 随着 Arm 推进 AGI CPU 芯片销售，晶圆厂（TSMC）及 substrates 供应链产能紧张可能成为限制芯片业务交付速度的关键物理瓶颈。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 地缘政治与 Arm China 独立性</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">区域合规与合资公司运营风险</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 跨国半导体 IP 授权极易受到全球贸易管制政策调整及 Arm China 独立运营合规性的潜在宏观扰动。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-armblue-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合仓位配置建议</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 核心成长底仓定位</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 作为全球半导体指令集与 AI 计算不可或缺的核心底座，建议在科技成长组合中配置核心底仓，充分享受云端与汽车 AI 长期红利。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-armblue-400 mb-1\">2. 动态分批逢低吸纳</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 鉴于 Arm 估值弹性较高，建议在宏观情绪调整引发股价回调时分批建仓，避免在极端情绪高点一次性重仓。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-teal-400 mb-1\">3. 跨产业链对冲策略</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 可与制造端（如台积电）及云基础设施应用厂商进行组合配置，平衡 IP 授权轻资产模式与芯片实体交付周期的双重属性。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 06. 季度基本面跟踪 KPI 核查清单 -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-armblue-500/15 text-armblue-600 dark:text-armblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选机构季报追踪已验证达标的指标（状态自动本地保存），用基本面事实校准 Arm 长期估值与成长动能：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0091BD] focus:ring-armblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. AGI CPU 芯片营收实现路径追踪 (FY27-FY28 ~$2B)</span>\n <span class=\"text-[11px] font-mono text-armblue-600 dark:text-armblue-400 font-semibold shrink-0\">芯片第二曲线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪 Arm 自研 AGI CPU 在各大云厂商（如 OCI、AWS、Google）的订单落地与实际交付进展。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0091BD] focus:ring-armblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. Neoverse CSS 与云端计算架构市占率是否达成 60%</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">数据中心渗透率</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核查 Graviton、Axion、Cobalt 及 NVIDIA 平台上 Arm 架构在云数据中心服务器的总体份额。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0091BD] focus:ring-armblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 年化合同价值 (ACV) 与 Total Access 客户拓展数</span>\n <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">授权签约质量</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监测 ACV 是否持续保持双位数增长，以及 Extant Total Access 长期授权客户数（当前 56 家）的扩张节奏。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0091BD] focus:ring-armblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. GAAP / Non-GAAP 毛利率是否保持 97% 以上极端高位</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">盈利质量防线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪在芯片硬件销售比重逐步上升的背景下，Arm 整体毛利率是否仍稳固在 97% 黄金区间。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0091BD] focus:ring-armblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 物理 AI 与智能汽车版税增速（是否维持 +50% YoY）</span>\n <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">边缘增量引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控智能汽车、ADAS 辅助驾驶及机器人（如 Robocar 400+ Arm 核心）版税收入的放量表现。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0091BD] focus:ring-armblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. Armv9 架构在移动与 AI PC 终端的出货占比提升</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">版税单价提升</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪 V9 架构渗透率提升带来的平均版税率（Royalty Rate）扩音器效应。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- 页脚免责声明 -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>安谋科技 Arm Holdings (NASDAQ: ARM) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：FY2026/FY2027 财报及 2026 年 11 月市场一致预期</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于 Arm Holdings 公开财报、投资者信件、半导体行业调研及市场一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的 FY27E 营收预测、AGI CPU 潜力、三情景估值模型均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出资产配置决策前，应结合自身风险承受能力审慎判断。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互脚本与 Chart.js -->\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-armblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-armblue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-armblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-armblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'core' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n const KPI_STORAGE_KEY = 'arm_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'evolution';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const evoConfig = {\n type: 'bar',\n data: {\n labels: ['FY2023', 'FY2024', 'FY2025', 'FY2026', 'FY2027E', 'FY2028E'],\n datasets: [\n {\n label: '版税收入 (Royalty Revenue)',\n data: [1.68, 1.78, 2.14, 2.65, 3.25, 4.10],\n backgroundColor: '#0091BD',\n borderRadius: 4,\n },\n {\n label: '许可与其他收入 (Licensing & Other)',\n data: [1.00, 1.45, 1.66, 1.35, 1.65, 2.00],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n },\n {\n label: 'AGI CPU 芯片收入 (Chip Revenue)',\n data: [0.0, 0.0, 0.0, 0.0, 0.80, 1.50],\n backgroundColor: '#10B981',\n borderRadius: 4,\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n stacked: true,\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n stacked: true,\n max: 8.0,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const splitConfig = {\n type: 'bar',\n data: {\n labels: [\n '移动设备 (Mobile - 99% 垄断)',\n '云与数据中心 (Cloud & Neoverse)',\n '汽车与物理智能 (Automotive & Edge)',\n '物联网与嵌入式 (IoT & Embedded)',\n 'AI 芯片拓展 (AGI CPU 计划)'\n ],\n datasets: [\n {\n label: '战略价值与营收占比贡献',\n data: [45, 25, 15, 10, 5],\n backgroundColor: [\n '#0091BD',\n '#3B82F6',\n '#06B6D4',\n '#64748B',\n '#10B981'\n ],\n borderRadius: 6,\n barThickness: 26\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `相对权重贡献: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 60,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnEvo = document.getElementById('btn-chart-evo');\n const btnSplit = document.getElementById('btn-chart-split');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'evolution') {\n btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-armblue-600 dark:text-armblue-400 shadow-sm transition';\n btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = 'FY2023–FY2028E 营收结构演进（授权费 vs 版税版图）';\n subEl.textContent = '版税收入稳居基本盘，CSS 与 AGI 芯片带来二次增长曲线';\n } else {\n btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-armblue-600 dark:text-armblue-400 shadow-sm transition';\n btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = 'Arm 各终端业务板块战略权重与长期价值拆解';\n subEl.textContent = '移动端基本盘稳定，云端 AI 与汽车物理智能为核心爆发点';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '软件开发者生态 (2200万+)',\n '能效比与指令集架构 (ISA)',\n '轻资产 IP 商业模式与高毛利',\n '生态伙伴与 CSS 客户粘性',\n '多终端覆盖广度 (手机/云/车)'\n ],\n datasets: [\n {\n label: 'Arm Holdings (ARM)',\n data: [9.9, 9.8, 9.9, 9.6, 9.8],\n borderColor: '#0091BD',\n backgroundColor: 'rgba(0, 145, 189, 0.22)',\n pointBackgroundColor: '#0091BD',\n borderWidth: 2.5\n },\n {\n label: '传统 x86 架构 (Intel / AMD)',\n data: [8.5, 6.8, 7.0, 7.5, 6.2],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.14)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 1.8\n },\n {\n label: '开源 RISC-V 阵营',\n data: [5.0, 8.2, 8.0, 5.5, 4.5],\n borderColor: '#94A3B8',\n backgroundColor: 'rgba(148, 163, 184, 0.12)',\n pointBackgroundColor: '#94A3B8',\n borderWidth: 1.5,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n 'Arm Holdings (ARM · 纯 IP 授权模式)',\n 'Broadcom (AVGO · 半导体与软件)',\n 'Qualcomm (QCOM · 移动芯片与授权)',\n 'AMD (AMD · 高性能计算芯片)',\n 'Intel (INTC · IDM 制造与芯片)'\n ],\n datasets: [{\n label: 'GAAP 毛利率 Gross Margin (%)',\n data: [97.1, 74.5, 56.2, 51.5, 38.4],\n backgroundColor: [\n '#0091BD',\n '#3B82F6',\n '#06B6D4',\n '#64748B',\n '#94A3B8'\n ],\n borderRadius: 6,\n barThickness: 22\n }]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `GAAP 毛利率: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 105,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['FY2023', 'FY2024', 'FY2025', 'FY2026', 'FY2027E', 'FY2028E'],\n datasets: [\n {\n type: 'bar',\n label: '总营收 Revenue ($B)',\n data: [2.68, 3.23, 3.80, 4.00, 6.06, 8.27],\n backgroundColor: 'rgba(0, 145, 189, 0.85)',\n borderRadius: 5,\n barThickness: 26,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '营收同比增速 YoY (%)',\n data: [0, 20.5, 17.6, 5.3, 51.5, 36.5],\n borderColor: '#F59E0B',\n backgroundColor: '#F59E0B',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y'\n ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n : `${ctx.dataset.label}: ${ctx.parsed.y}%`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n max: 10,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: -10,\n max: 70,\n grid: { drawOnChartArea: false },\n ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + '%' }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
